export const ZohoTicketToolIcon = icon(TicketStarIcon, "ZohoTicketToolIcon")

"use client"

import * as React from "react"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty"
import { Field, FieldDescription, FieldLabel } from "@/components/ui/field"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  ConfiguredIcon,
  DismissIcon,
  UnsavedIcon,
} from "@/components/mockups/scenario-single-screen/icons"
import { SheetSection } from "@/components/mockups/scenario-single-screen/setting-sheet"
import {
  CURRENT_ORGANIZATION,
  type Insight,
  type InsightTarget,
  type Opportunity,
  ORGANIZATIONS,
} from "@/lib/mockups/scenario-single-screen-data"

const TARGET_LABELS: Record<InsightTarget, string> = {
  criteria: "success criteria",
  extraction: "data extraction",
  knowledge: "knowledge bases",
  prompt: "the prompt",
  tools: "tools",
}

export function InsightsDrawerBody({
  dismissed,
  insights,
  onDismiss,
  onOpenTarget,
}: {
  dismissed: string[]
  insights: Insight[]
  onDismiss: (title: string) => void
  onOpenTarget: (target: InsightTarget) => void
}) {
  const open = insights.filter((insight) => !dismissed.includes(insight.title))

  if (open.length === 0) {
    return (
      <Empty>
        <EmptyHeader>
          <EmptyMedia variant="icon">
            <ConfiguredIcon />
          </EmptyMedia>
          <EmptyTitle>Nothing left to review</EmptyTitle>
          <EmptyDescription>
            New insights appear as calls come in.
          </EmptyDescription>
        </EmptyHeader>
      </Empty>
    )
  }

  return (
    <div className="flex flex-col gap-3">
      {open.map((insight) => (
        <Card key={insight.title} size="sm">
          <CardContent className="flex flex-col gap-3">
            <div className="flex flex-col gap-1">
              <p className="text-sm font-medium">{insight.title}</p>
              <p className="text-sm text-muted-foreground">{insight.body}</p>
            </div>
            <div className="flex flex-wrap items-center gap-2">
              <Badge variant="secondary">{insight.calls} calls</Badge>
              <div className="flex-1" />
              <Button
                onClick={() => {
                  onDismiss(insight.title)
                }}
                size="xs"
                variant="ghost"
              >
                <DismissIcon />
                Dismiss
              </Button>
              <Button
                onClick={() => {
                  onOpenTarget(insight.target)
                }}
                size="xs"
                variant="outline"
              >
                Open {TARGET_LABELS[insight.target]}
              </Button>
            </div>
          </CardContent>
        </Card>
      ))}
    </div>
  )
}

const IMPACT_VARIANT = {
  high: "default",
  low: "outline",
  medium: "secondary",
} as const

export function OpportunitiesDrawerBody({
  opportunities,
}: {
  opportunities: Opportunity[]
}) {
  return (
    <div className="flex flex-col gap-3">
      {opportunities.map((opportunity) => (
        <Card key={opportunity.title} size="sm">
          <CardContent className="flex flex-col gap-3">
            <div className="flex items-start justify-between gap-3">
              <p className="text-sm font-medium">{opportunity.title}</p>
              <Badge variant={IMPACT_VARIANT[opportunity.impact]}>
                {opportunity.impact} impact
              </Badge>
            </div>
            <p className="text-sm text-muted-foreground">
              {opportunity.detail}
            </p>
          </CardContent>
        </Card>
      ))}
    </div>
  )
}

export function OwnershipDrawerBody({
  attachedBases,
}: {
  attachedBases: number
}) {
  const [organization, setOrganization] = React.useState(CURRENT_ORGANIZATION)
  const moving = organization !== CURRENT_ORGANIZATION

  return (
    <SheetSection title="Owning organization">
      <Field>
        <FieldLabel htmlFor="owner-organization">Organization</FieldLabel>
        <Select onValueChange={setOrganization} value={organization}>
          <SelectTrigger id="owner-organization">
            <SelectValue />
          </SelectTrigger>
          <SelectContent position="popper">
            {ORGANIZATIONS.map((name) => (
              <SelectItem key={name} value={name}>
                {name}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <FieldDescription>
          Currently owned by {CURRENT_ORGANIZATION}.
        </FieldDescription>
      </Field>

      {moving ? (
        <Alert variant="destructive">
          <UnsavedIcon />
          <AlertTitle>
            {attachedBases} knowledge bases will be detached
          </AlertTitle>
          <AlertDescription>
            Knowledge bases do not move between organizations. Reattach the
            equivalents in {organization} before the next publish.
          </AlertDescription>
        </Alert>
      ) : null}

      <Button disabled={!moving} variant="destructive">
        Transfer to {organization}
      </Button>
    </SheetSection>
  )
}

"use client"

import * as React from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Separator } from "@/components/ui/separator"
import { Switch } from "@/components/ui/switch"
import { Textarea } from "@/components/ui/textarea"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import {
  CriteriaDrawerBody,
  ExtractionDrawerBody,
  KnowledgeDrawerBody,
  LanguagesDrawerBody,
  PersonaDrawerBody,
  RecordingDrawerBody,
  ToolsDrawerBody,
  VariablesDrawerBody,
} from "@/components/mockups/scenario-single-screen/config-drawers"
import {
  CriteriaIcon,
  ExtractionIcon,
  InsightsIcon,
  KnowledgeIcon,
  LanguagesIcon,
  OpportunitiesIcon,
  OwnershipIcon,
  PersonaIcon,
  PublishIcon,
  RecordingIcon,
  TestCallIcon,
  TimezoneIcon,
  ToolsIcon,
  UnsavedIcon,
  VariablesIcon,
} from "@/components/mockups/scenario-single-screen/icons"
import {
  InsightsDrawerBody,
  OpportunitiesDrawerBody,
  OwnershipDrawerBody,
} from "@/components/mockups/scenario-single-screen/review-drawers"
import {
  RailGroup,
  SettingRow,
} from "@/components/mockups/scenario-single-screen/setting-rail"
import { SettingSheet } from "@/components/mockups/scenario-single-screen/setting-sheet"
import {
  DATA_EXTRACTION,
  DEFAULT_LANGUAGE,
  DESTINATIONS,
  type Destination,
  INSIGHTS,
  type InsightTarget,
  KNOWLEDGE_BASES,
  LANGUAGE_LABELS,
  LANGUAGE_SHORT,
  type LanguageCode,
  OPPORTUNITIES,
  PER_LANGUAGE,
  RECORD_SINKS,
  SCENARIO,
  SUCCESS_CRITERIA,
  TEMPLATE_VARIABLES,
  TIMEZONE,
  TOOLS,
  type ToolSlug,
  UNRESOLVED_INSIGHTS,
} from "@/lib/mockups/scenario-single-screen-data"

type Setting =
  | "criteria"
  | "extraction"
  | "insights"
  | "knowledge"
  | "languages"
  | "opportunities"
  | "ownership"
  | "persona"
  | "recording"
  | "timezone"
  | "tools"
  | "variables"

const INSIGHT_TARGETS: Record<InsightTarget, Setting | null> = {
  criteria: "criteria",
  extraction: "extraction",
  knowledge: "knowledge",
  prompt: null,
  tools: "tools",
}

export function ScenarioEditor({ isStaff }: { isStaff: boolean }) {
  const [openSetting, setOpenSetting] = React.useState<Setting | null>(null)
  const [dirty, setDirty] = React.useState(false)

  const [language, setLanguage] = React.useState<LanguageCode>(DEFAULT_LANGUAGE)
  const [defaultLanguage, setDefaultLanguage] =
    React.useState<LanguageCode>(DEFAULT_LANGUAGE)
  const [perLanguage, setPerLanguage] = React.useState(PER_LANGUAGE)
  const [timezone, setTimezone] = React.useState(TIMEZONE)
  const [bases, setBases] = React.useState(KNOWLEDGE_BASES)
  const [tools, setTools] = React.useState(TOOLS)
  const [criteria, setCriteria] = React.useState(SUCCESS_CRITERIA)
  const [variables, setVariables] = React.useState(TEMPLATE_VARIABLES)
  const [extractionOn, setExtractionOn] = React.useState(
    DATA_EXTRACTION.enabled,
  )
  const [destinations, setDestinations] = React.useState(DESTINATIONS)
  const [zohoRecording, setZohoRecording] = React.useState(
    RECORD_SINKS.zohoCallActivity,
  )
  const [dismissedInsights, setDismissedInsights] = React.useState<string[]>([])

  const edit = <T,>(setter: (value: T) => void) => {
    return (value: T) => {
      setter(value)
      setDirty(true)
    }
  }

  const current =
    perLanguage.find((entry) => entry.language === language) ?? perLanguage[0]

  const updateCurrent = (patch: Partial<(typeof perLanguage)[number]>) => {
    setPerLanguage((entries) =>
      entries.map((entry) =>
        entry.language === language ? { ...entry, ...patch } : entry,
      ),
    )
    setDirty(true)
  }

  const spokenLanguages = perLanguage.map((entry) => entry.language)
  const attachedBases = bases.filter((base) => base.attached)
  const enabledTools = tools.filter((tool) => tool.enabled)
  const enabledDestinations = destinations.filter(
    (destination) => destination.enabled,
  )
  const openInsights = UNRESOLVED_INSIGHTS - dismissedInsights.length

  const reset = () => {
    setPerLanguage(PER_LANGUAGE)
    setDefaultLanguage(DEFAULT_LANGUAGE)
    setTimezone(TIMEZONE)
    setBases(KNOWLEDGE_BASES)
    setTools(TOOLS)
    setCriteria(SUCCESS_CRITERIA)
    setVariables(TEMPLATE_VARIABLES)
    setExtractionOn(DATA_EXTRACTION.enabled)
    setDestinations(DESTINATIONS)
    setZohoRecording(RECORD_SINKS.zohoCallActivity)
    setDirty(false)
  }

  return (
    <div className="flex flex-1 flex-col p-3 lg:p-4">
      <div className="mx-auto flex w-full max-w-350 flex-col gap-6">
        <header className="flex flex-wrap items-start justify-between gap-4">
          <div className="flex min-w-0 flex-col gap-1">
            <div className="flex flex-wrap items-center gap-2">
              <h1 className="text-2xl font-semibold">{SCENARIO.name}</h1>
              <Badge className="bg-success/10 text-success">Active</Badge>
            </div>
            {/* The four numbers the header carried before, as one line. They
                are context for the editing below, not a dashboard. */}
            <p className="text-sm text-muted-foreground">
              {SCENARIO.calls.toLocaleString()} calls · {SCENARIO.successRate}%
              met success criteria · Created {SCENARIO.createdAt} · Published{" "}
              {SCENARIO.lastPublished}
            </p>
          </div>

          <div className="flex shrink-0 items-center gap-2">
            <Button
              onClick={() => {
                setOpenSetting("insights")
              }}
              variant="outline"
            >
              <InsightsIcon />
              Insights
              <Badge variant="secondary">{openInsights}</Badge>
            </Button>
            <Button variant="outline">
              <TestCallIcon />
              Test
            </Button>
            <Button>
              <PublishIcon />
              Publish
            </Button>
          </div>
        </header>

        <div className="flex flex-col gap-6 lg:flex-row lg:items-start">
          {/* What the agent says. The only thing on this screen a person
              writes rather than picks, so it gets the width. */}
          <div className="flex min-w-0 flex-1 flex-col gap-4">
            <div className="flex flex-wrap items-center justify-between gap-3">
              <p className="text-sm text-muted-foreground">
                Writing the {LANGUAGE_LABELS[current.language]} version
                {current.language === defaultLanguage ? " — the default" : ""}
              </p>
              <ToggleGroup
                onValueChange={(next) => {
                  if (next) setLanguage(next as LanguageCode)
                }}
                size="sm"
                type="single"
                value={language}
                variant="outline"
              >
                {perLanguage.map((entry) => (
                  <ToggleGroupItem
                    aria-label={LANGUAGE_LABELS[entry.language]}
                    key={entry.language}
                    value={entry.language}
                  >
                    {LANGUAGE_SHORT[entry.language]}
                  </ToggleGroupItem>
                ))}
              </ToggleGroup>
            </div>

            <Card>
              <CardHeader>
                <CardTitle>First message</CardTitle>
                <CardDescription>
                  What the agent opens the call with. Leave it off to let the
                  caller speak first.
                </CardDescription>
                <CardAction>
                  <Switch
                    aria-label="First message"
                    checked={current.firstMessageEnabled}
                    onCheckedChange={(checked) => {
                      updateCurrent({ firstMessageEnabled: checked })
                    }}
                  />
                </CardAction>
              </CardHeader>
              <CardContent>
                <Input
                  aria-label="First message"
                  dir={
                    current.language === "ar" || current.language === "ur"
                      ? "rtl"
                      : "ltr"
                  }
                  disabled={!current.firstMessageEnabled}
                  onChange={(event) => {
                    updateCurrent({ firstMessage: event.target.value })
                  }}
                  value={current.firstMessage}
                />
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle>Instruction prompt</CardTitle>
                <CardDescription>
                  How the agent behaves for the whole call.
                </CardDescription>
              </CardHeader>
              <CardContent className="flex flex-col gap-4">
                <Textarea
                  aria-label="Instruction prompt"
                  className="min-h-140 font-mono"
                  dir={
                    current.language === "ar" || current.language === "ur"
                      ? "rtl"
                      : "ltr"
                  }
                  onChange={(event) => {
                    updateCurrent({ prompt: event.target.value })
                  }}
                  value={current.prompt}
                />

                <Separator />

                {/* Variables belong under the prompt that spends them, not in
                    a table of their own further down the page. The chips are
                    the whole list; the drawer is where types and defaults
                    live. */}
                <div className="flex flex-wrap items-center gap-2">
                  <span className="text-sm text-muted-foreground">
                    Variables
                  </span>
                  {variables.map((variable) => (
                    <Badge
                      className="font-mono"
                      key={variable.name}
                      variant="outline"
                    >
                      {`{{${variable.name}}}`}
                    </Badge>
                  ))}
                  <Button
                    onClick={() => {
                      setOpenSetting("variables")
                    }}
                    size="xs"
                    variant="ghost"
                  >
                    Manage
                  </Button>
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Everything the scenario is set to, readable without opening a
              thing. The rail is the replacement for the Configuration tab. */}
          <aside className="flex w-full shrink-0 flex-col gap-4 lg:sticky lg:top-4 lg:w-96">
            <RailGroup title="How it speaks">
              <SettingRow
                icon={PersonaIcon}
                onOpen={() => {
                  setOpenSetting("persona")
                }}
                title="Persona"
                value={current.persona}
              />
              <SettingRow
                icon={LanguagesIcon}
                onOpen={() => {
                  setOpenSetting("languages")
                }}
                title="Languages"
                value={`${spokenLanguages
                  .map((code) => LANGUAGE_LABELS[code])
                  .join(", ")} · ${LANGUAGE_LABELS[defaultLanguage]} default`}
              />
              <SettingRow
                icon={TimezoneIcon}
                onOpen={() => {
                  setOpenSetting("timezone")
                }}
                title="Timezone"
                value={timezone}
              />
            </RailGroup>

            <RailGroup title="What it knows and can do">
              <SettingRow
                icon={KnowledgeIcon}
                onOpen={() => {
                  setOpenSetting("knowledge")
                }}
                title="Knowledge bases"
                value={
                  attachedBases.length === 0
                    ? "None attached"
                    : attachedBases.map((base) => base.name).join(", ")
                }
              />
              <SettingRow
                icon={ToolsIcon}
                onOpen={() => {
                  setOpenSetting("tools")
                }}
                title="Tools"
                value={
                  enabledTools.length === 0
                    ? "None enabled"
                    : enabledTools.map((tool) => tool.label).join(", ")
                }
              />
              <SettingRow
                icon={VariablesIcon}
                onOpen={() => {
                  setOpenSetting("variables")
                }}
                title="Template variables"
                value={`${variables.length} · ${
                  variables.filter((variable) => variable.required).length
                } required`}
              />
            </RailGroup>

            <RailGroup title="When the call ends">
              <SettingRow
                icon={CriteriaIcon}
                onOpen={() => {
                  setOpenSetting("criteria")
                }}
                title="Success criteria"
                value={`${criteria.length} criteria · ${
                  criteria.filter((criterion) => criterion.primary).length
                } primary`}
              />
              <SettingRow
                icon={ExtractionIcon}
                onOpen={() => {
                  setOpenSetting("extraction")
                }}
                title="Data extraction"
                value={
                  extractionOn
                    ? `${DATA_EXTRACTION.fields.length} fields → ${
                        enabledDestinations.length === 0
                          ? "nowhere yet"
                          : enabledDestinations
                              .map((destination) => destination.label)
                              .join(", ")
                      }`
                    : "Off"
                }
              />
              <SettingRow
                icon={RecordingIcon}
                onOpen={() => {
                  setOpenSetting("recording")
                }}
                title="Recording delivery"
                value={zohoRecording ? "Zoho call activity" : "Not delivered"}
              />
            </RailGroup>

            {isStaff ? (
              <RailGroup title="Sarj staff">
                <SettingRow
                  icon={OpportunitiesIcon}
                  onOpen={() => {
                    setOpenSetting("opportunities")
                  }}
                  title="Optimization opportunities"
                  value={`${OPPORTUNITIES.length} open`}
                />
                <SettingRow
                  icon={OwnershipIcon}
                  onOpen={() => {
                    setOpenSetting("ownership")
                  }}
                  title="Owning organization"
                  value="Sizzler KSA"
                />
              </RailGroup>
            ) : null}
          </aside>
        </div>
      </div>

      {/* One save bar for the page and every drawer on it, so there is a
          single answer to "is this live yet". */}
      {dirty ? (
        <div className="sticky bottom-4 z-sticky mx-auto mt-6 w-full max-w-350">
          <Card>
            <CardContent className="flex flex-wrap items-center justify-between gap-4">
              <div className="flex items-center gap-2">
                <span className="text-warning">
                  <UnsavedIcon />
                </span>
                <p className="text-sm font-medium">You have unsaved changes</p>
              </div>
              <div className="flex items-center gap-2">
                <Button onClick={reset} variant="outline">
                  Clear
                </Button>
                <Button
                  onClick={() => {
                    setDirty(false)
                  }}
                >
                  Save
                </Button>
              </div>
            </CardContent>
          </Card>
        </div>
      ) : null}

      {/* --- the drawers ------------------------------------------------- */}

      <SettingSheet
        description="One voice per language. The persona also carries the turn timing and backchannel settings that language uses."
        onOpenChange={(open) => {
          setOpenSetting(open ? "persona" : null)
        }}
        open={openSetting === "persona"}
        title="Persona"
      >
        <PersonaDrawerBody
          onPersonaChange={(code, persona) => {
            setPerLanguage((entries) =>
              entries.map((entry) =>
                entry.language === code ? { ...entry, persona } : entry,
              ),
            )
            setDirty(true)
          }}
          perLanguage={perLanguage}
        />
      </SettingSheet>

      <SettingSheet
        description="Each language keeps its own prompt, first message and persona."
        onOpenChange={(open) => {
          setOpenSetting(open ? "languages" : null)
        }}
        open={openSetting === "languages" || openSetting === "timezone"}
        title="Languages and timezone"
      >
        <LanguagesDrawerBody
          defaultLanguage={defaultLanguage}
          onDefaultChange={edit(setDefaultLanguage)}
          onTimezoneChange={edit(setTimezone)}
          perLanguage={perLanguage}
          timezone={timezone}
        />
      </SettingSheet>

      <SettingSheet
        description="Attached bases are searched when the agent needs a fact it was not told."
        onOpenChange={(open) => {
          setOpenSetting(open ? "knowledge" : null)
        }}
        open={openSetting === "knowledge"}
        title="Knowledge bases"
      >
        <KnowledgeDrawerBody
          bases={bases}
          onToggle={(name) => {
            setBases((entries) =>
              entries.map((base) =>
                base.name === name
                  ? { ...base, attached: !base.attached }
                  : base,
              ),
            )
            setDirty(true)
          }}
          spokenLanguages={spokenLanguages}
        />
      </SettingSheet>

      <SettingSheet
        description="Actions the agent can take during a call, beyond talking."
        onOpenChange={(open) => {
          setOpenSetting(open ? "tools" : null)
        }}
        open={openSetting === "tools"}
        title="Tools"
      >
        <ToolsDrawerBody
          onToggle={(slug: ToolSlug) => {
            setTools((entries) =>
              entries.map((tool) =>
                tool.slug === slug ? { ...tool, enabled: !tool.enabled } : tool,
              ),
            )
            setDirty(true)
          }}
          tools={tools}
        />
      </SettingSheet>

      <SettingSheet
        description="What a call has to achieve to be scored as successful."
        onOpenChange={(open) => {
          setOpenSetting(open ? "criteria" : null)
        }}
        open={openSetting === "criteria"}
        title="Success criteria"
      >
        <CriteriaDrawerBody
          criteria={criteria}
          onCriteriaChange={edit(setCriteria)}
        />
      </SettingSheet>

      <SettingSheet
        description="Placeholders the prompt and first message fill in when a call starts."
        onOpenChange={(open) => {
          setOpenSetting(open ? "variables" : null)
        }}
        open={openSetting === "variables"}
        title="Template variables"
      >
        <VariablesDrawerBody
          onVariablesChange={edit(setVariables)}
          variables={variables}
        />
      </SettingSheet>

      <SettingSheet
        description="Fields read out of the transcript when the call ends, and where they go."
        onOpenChange={(open) => {
          setOpenSetting(open ? "extraction" : null)
        }}
        open={openSetting === "extraction"}
        title="Data extraction"
      >
        <ExtractionDrawerBody
          destinations={destinations}
          enabled={extractionOn}
          fields={DATA_EXTRACTION.fields}
          onDestinationToggle={(type: Destination["type"]) => {
            setDestinations((entries) =>
              entries.map((destination) =>
                destination.type === type
                  ? { ...destination, enabled: !destination.enabled }
                  : destination,
              ),
            )
            setDirty(true)
          }}
          onEnabledChange={edit(setExtractionOn)}
        />
      </SettingSheet>

      <SettingSheet
        description="Where the call recording is sent once the call ends."
        onOpenChange={(open) => {
          setOpenSetting(open ? "recording" : null)
        }}
        open={openSetting === "recording"}
        title="Recording delivery"
      >
        <RecordingDrawerBody
          onZohoChange={edit(setZohoRecording)}
          zohoCallActivity={zohoRecording}
        />
      </SettingSheet>

      <SettingSheet
        description="What the last 90 days of calls say about this scenario."
        onOpenChange={(open) => {
          setOpenSetting(open ? "insights" : null)
        }}
        open={openSetting === "insights"}
        title="Insights"
      >
        <InsightsDrawerBody
          dismissed={dismissedInsights}
          insights={INSIGHTS}
          onDismiss={(title) => {
            setDismissedInsights((titles) => [...titles, title])
          }}
          onOpenTarget={(target) => {
            setOpenSetting(INSIGHT_TARGETS[target])
          }}
        />
      </SettingSheet>

      <SettingSheet
        description="Cost and quality wins Sarj staff can act on for this scenario."
        onOpenChange={(open) => {
          setOpenSetting(open ? "opportunities" : null)
        }}
        open={openSetting === "opportunities"}
        title="Optimization opportunities"
      >
        <OpportunitiesDrawerBody opportunities={OPPORTUNITIES} />
      </SettingSheet>

      <SettingSheet
        description="Move this scenario to another organization."
        onOpenChange={(open) => {
          setOpenSetting(open ? "ownership" : null)
        }}
        open={openSetting === "ownership"}
        title="Owning organization"
      >
        <OwnershipDrawerBody attachedBases={attachedBases.length} />
      </SettingSheet>
    </div>
  )
}

"use client"

import * as React from "react"

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemGroup,
  ItemMedia,
  ItemTitle,
} from "@/components/ui/item"
import { OpenSettingIcon } from "@/components/mockups/scenario-single-screen/icons"

export function SettingRow({
  icon: Icon,
  onOpen,
  title,
  value,
}: {
  icon: React.ComponentType
  onOpen: () => void
  title: string
  value: string
}) {
  return (
    <Item asChild size="sm">
      <button
        className="cursor-pointer text-start hover:bg-accent"
        onClick={onOpen}
        type="button"
      >
        <ItemMedia variant="icon">
          <Icon />
        </ItemMedia>
        <ItemContent>
          <ItemTitle>{title}</ItemTitle>
          <ItemDescription>{value}</ItemDescription>
        </ItemContent>
        <ItemActions className="text-muted-foreground">
          <OpenSettingIcon />
        </ItemActions>
      </button>
    </Item>
  )
}

export function RailGroup({
  children,
  title,
}: {
  children: React.ReactNode
  title: string
}) {
  return (
    <Card size="sm">
      <CardHeader>
        <CardTitle className="text-muted-foreground">{title}</CardTitle>
      </CardHeader>
      <CardContent>
        <ItemGroup className="gap-0">{children}</ItemGroup>
      </CardContent>
    </Card>
  )
}

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { ScrollArea } from "@/components/ui/scroll-area"
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet"

/** `sm:max-w-xl!`: SheetContent's `data-[side=right]:sm:max-w-sm` outranks a plain utility. */
export function SettingSheet({
  children,
  description,
  onOpenChange,
  open,
  title,
}: {
  children: React.ReactNode
  description: string
  onOpenChange: (open: boolean) => void
  open: boolean
  title: string
}) {
  return (
    <Sheet onOpenChange={onOpenChange} open={open}>
      <SheetContent className="gap-0 p-0 sm:max-w-xl!" side="right">
        <SheetHeader className="border-b pe-12">
          <SheetTitle>{title}</SheetTitle>
          <SheetDescription>{description}</SheetDescription>
        </SheetHeader>

        <ScrollArea className="min-h-0 flex-1">
          <div className="flex flex-col gap-6 p-4">{children}</div>
        </ScrollArea>

        {/* Row, not the primitive's stacked column: one button that closes a
            panel is not a page-width commitment, and drawing it as one makes
            it read like a save. */}
        <SheetFooter className="flex-row justify-end border-t">
          <Button
            onClick={() => {
              onOpenChange(false)
            }}
          >
            Done
          </Button>
        </SheetFooter>
      </SheetContent>
    </Sheet>
  )
}

export function SheetSection({
  children,
  description,
  title,
}: {
  children: React.ReactNode
  description?: string
  title: string
}) {
  return (
    <section className="flex flex-col gap-3">
      <div className="flex flex-col gap-0.5">
        <h3 className="text-sm font-medium">{title}</h3>
        {description ? (
          <p className="text-sm text-muted-foreground">{description}</p>
        ) : null}
      </div>
      {children}
    </section>
  )
}

"use client"

import * as React from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  Field,
  FieldContent,
  FieldDescription,
  FieldGroup,
  FieldLabel,
  FieldTitle,
} from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@/components/ui/input-group"
import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemGroup,
  ItemMedia,
  ItemTitle,
} from "@/components/ui/item"
import { Label } from "@/components/ui/label"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Switch } from "@/components/ui/switch"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { Textarea } from "@/components/ui/textarea"
import {
  AddIcon,
  CollectDigitsToolIcon,
  EndCallToolIcon,
  FindIcon,
  HttpRequestToolIcon,
  IvrToolIcon,
  RemoveIcon,
  SallaToolIcon,
  SwitchLanguageToolIcon,
  TransferToolIcon,
  VoicemailToolIcon,
  ZohoTicketToolIcon,
} from "@/components/mockups/scenario-single-screen/v2/icons"
import { SheetSection } from "@/components/mockups/scenario-single-screen/v2/setting-sheet"
import {
  type Destination,
  type ExtractionField,
  type KnowledgeBase,
  LANGUAGE_LABELS,
  type LanguageCode,
  type PerLanguage,
  PERSONAS,
  type SuccessCriterion,
  type TemplateVariable,
  type Tool,
  type ToolSlug,
} from "@/lib/mockups/scenario-single-screen-data"

const TIMEZONES = [
  "Asia/Riyadh",
  "Asia/Dubai",
  "Asia/Karachi",
  "Africa/Cairo",
  "Europe/London",
]

const TOOL_ICONS: Record<ToolSlug, React.ComponentType> = {
  "code-switching": SwitchLanguageToolIcon,
  "collect-digits": CollectDigitsToolIcon,
  "custom-api": HttpRequestToolIcon,
  "end-call": EndCallToolIcon,
  "ivr-navigation": IvrToolIcon,
  "salla-tools": SallaToolIcon,
  "transfer-to-human": TransferToolIcon,
  "voicemail-detection": VoicemailToolIcon,
  "zoho-desk-create-ticket": ZohoTicketToolIcon,
}

export function PersonaDrawerBody({
  onPersonaChange,
  perLanguage,
}: {
  onPersonaChange: (language: LanguageCode, persona: string) => void
  perLanguage: PerLanguage[]
}) {
  return (
    <FieldGroup>
      {perLanguage.map((entry) => (
        <Field key={entry.language}>
          <FieldLabel htmlFor={`persona-${entry.language}`}>
            {LANGUAGE_LABELS[entry.language]}
          </FieldLabel>
          <Select
            onValueChange={(persona) => {
              onPersonaChange(entry.language, persona)
            }}
            value={entry.persona}
          >
            <SelectTrigger id={`persona-${entry.language}`}>
              <SelectValue placeholder="Select a persona" />
            </SelectTrigger>
            <SelectContent position="popper">
              {PERSONAS.map((persona) => (
                <SelectItem key={persona} value={persona}>
                  {persona}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <FieldDescription>
            Speaks the {LANGUAGE_LABELS[entry.language]} prompt and first
            message.
